"""Self-contained full-asset galleries and native-inspired screen studies (not device screenshots)."""
from pathlib import Path
import html,json,shutil
from build_advanced_worlds import COLLECTION,ROOT
from render_illustrated_gallery import CSS as ASSET_CSS
OUT=ROOT.parent/'outputs-unused'
def glyph(a,p,k,size=24):
 return f'<img width="{size}" height="{size}" src="{p}{a[k]}" alt="{k.replace("_"," ")}">' if k in a else ''
def shape(style):return {'pixel':'6px','botanical':'28px 10px 28px 10px','deco':'9px','telemetry':'4px 18px 4px 18px','flame':'4px 28px 4px 28px'}[style]
def track(m):
 p=m['palette'];style=m['seekStyle'];items=[]
 for i in range(24):
  x=i*12.5;c=p['background'] if x<114 else p['secondary']
  if style=='road':items.append(f'<rect x="{x+2}" y="4" width="6" height="2" fill="{c}"/>')
  elif style=='vine':items.append(f'<path d="M{x} 5q6 -7 11 0q-6 7 -11 0" fill="{c}"/>')
  elif style=='skyline':items.append(f'<rect x="{x}" y="{2+i%5}" width="7" height="{8-i%5}" fill="{c}"/>')
  elif style=='telemetry':items.append(f'<path d="M{x} 10l4 -{9 if i%4==0 else 4}" stroke="{c}"/>')
  else:items.append(f'<path d="M{x} 9q-2 -4 3 -8q-2 6 5 8Z" fill="{c}"/>')
 return f'<svg class="track" viewBox="0 0 300 10" aria-label="Sample progress at 38 percent"><rect width="300" height="10" rx="4" fill="{p["outline"]}"/><rect width="114" height="10" rx="4" fill="{p["accent"]}"/>{"".join(items)}<rect x="110" y="1" width="8" height="8" rx="2" fill="{p["text"]}"/></svg>'
CSS='''*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:Body,sans-serif}main{max-width:1440px;padding:45px;margin:auto}h1,h2,h3{font-family:Heading}h1{font-size:68px;margin:8px 0}h2{font-size:34px;margin:30px 0 15px}p{color:var(--muted);line-height:1.6}small{color:var(--accent);font-size:11px;letter-spacing:1px}header{display:flex;justify-content:space-between;align-items:center;padding-bottom:20px;border-bottom:1px solid var(--outline)}header img{width:100px;height:100px}.phones{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:25px;margin:30px 0}.phone{height:860px;border:1px solid var(--outline);border-radius:32px;overflow:hidden;background:linear-gradient(var(--scrim),var(--scrim)),var(--art) center/cover;position:relative;padding:24px 20px 90px}.phone h2{font-size:36px}.phone h3{font-size:24px;margin:20px 0 10px}.phone p{font-size:13px}.top{display:flex;justify-content:space-between;align-items:center;font-size:11px;color:var(--muted);height:38px}.brand{display:flex;align-items:center;gap:12px;margin:22px 0}.brand img{width:48px;height:48px}.brand strong{font-family:Heading;font-size:43px}.row{display:flex;justify-content:space-between;align-items:center;gap:12px;margin:10px 0}.row span{flex:1}.row em{display:block;font-style:normal;font-size:11px;color:var(--muted);margin-top:5px}.panel,.button{border:1px solid var(--outline);border-radius:var(--radius);background:var(--surface)}.panel{padding:14px;margin:16px 0}.button{display:flex;align-items:center;justify-content:center;width:44px;height:44px;background:var(--raised);flex-shrink:0}.button img{width:22px;height:22px}.hero{height:132px;background:linear-gradient(0deg,var(--bg),transparent),var(--art) center 70%/cover;border:1px solid var(--outline);border-radius:var(--radius);padding:16px;display:flex;align-items:flex-end;font-family:Heading;font-size:27px}.navbar{position:absolute;bottom:20px;left:16px;right:16px;display:flex;align-items:center;justify-content:space-around;padding:10px;border-radius:var(--radius);border:1px solid var(--outline);background:var(--surface)}.navbar span{text-align:center;font-size:9px;color:var(--muted)}.navbar img{display:block;margin:auto auto 5px;width:23px;height:23px}.album{height:235px;border-radius:var(--radius);background:var(--art) center 65%/cover;border:1px solid var(--outline);margin:16px 0}.controls{display:flex;align-items:center;justify-content:space-around;margin:24px 0}.play{width:76px;height:76px;background:var(--container)}.play img{width:38px;height:38px}.track{display:block;width:100%;height:10px;margin-top:15px}.time{display:flex;justify-content:space-between;font-size:10px;color:var(--muted);margin-top:8px}.switch{display:flex;align-items:center;background:var(--accent);border-radius:var(--radius);padding:5px 5px 5px 20px}.switch img{width:18px;height:18px;background:var(--surface);border-radius:var(--radius);padding:2px}.settings .panel .row{padding:8px 0;border-bottom:1px solid var(--outline)}.settings .panel .row:last-child{border:0}.note{font-size:12px}.strip{display:flex;gap:12px;align-items:center;margin-top:30px;border-top:1px solid var(--outline);padding-top:20px}.strip img{width:26px;height:26px}.palette{display:flex;gap:10px;margin-top:20px}.palette i{width:34px;height:14px;border-radius:5px;border:1px solid var(--outline)}a{color:var(--accent)}.coverage{columns:3;line-height:1.8;font-size:12px;color:var(--muted)}@media(max-width:900px){main{padding:20px}.phones{grid-template-columns:1fr}.phone{max-width:400px;width:100%;margin:auto}h1{font-size:42px}}@media(prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important}}'''
def make(c,prefix):
 m=json.loads((ROOT/c['id']/'theme.json').read_text());a=m['assets'];p=m['palette'];g=lambda key,n=24:glyph(a,prefix,key,n)
 vars=':root{'+''.join('--'+{'background':'bg','accentContainer':'container'}.get(k,k)+':'+v+';' for k,v in p.items())+f'--radius:{shape(c["material"])};--scrim:{p["background"]}c4;--art:url({prefix}{a["header"]});'+'}'
 fonts=f'@font-face{{font-family:Heading;src:url({prefix}{a["headingFont"]})}}@font-face{{font-family:Body;src:url({prefix}{a["bodyFont"]})}}'
 button=lambda key,extra='':f'<div class="button {extra}">{g(key)}</div>'
 nav='<div class="navbar">'+''.join(f'<span>{g(k)}{label}</span>' for k,label in [('nav_home','Home'),('nav_search','Search'),('nav_explore','Explore'),('nav_library','Library')])+'</div>'
 top=f'<div class="top"><span>9:41 &nbsp; VEYRA</span>{button("account")}</div>'
 home=f'''<article class="phone">{top}<div class="brand">{g('brandIcon')}<strong>Veyra</strong></div><h2>Listen now.</h2><p>{c['tagline']}</p><div class="row"><h3>Your frequency</h3>{button('sound')}</div><div class="hero">Made for this moment</div><div class="panel"><div class="row">{g('music')}<span>Keep the feeling<em>A little further, a little louder</em></span>{g('play')}</div></div><div class="row"><h3>Quick picks</h3>{g('grid')}</div><div class="row">{button('heart')}{button('history')}{button('add')}{button('download')}</div>{nav}</article>'''
 player=f'''<article class="phone"><div class="top">{button('back')}<span>NOW PLAYING</span>{button('more')}</div><div class="album"></div><div class="row"><span><h3>{c['tagline']}</h3><em>Theme artwork · player study</em></span>{g('heart_filled')}</div>{track(m)}<div class="time"><span>1:24</span><span>−2:18</span></div><div class="controls">{button('previous')}{button('play','play')}{button('next')}</div><div class="row">{g('volume_down')}{track(m)}{g('volume_up')}</div><div class="controls">{button('lyrics')}{button('shuffle')}{button('repeat')}{button('queue')}</div><p style="text-align:center">This phone &nbsp; · &nbsp; {c['material'].title()}</p></article>'''
 rows=''.join(f'<div class="row">{g(k)}<span>{t}<em>{s}</em></span>{g("chevron",18)}</div>' for k,t,s in [('account','Account & connections','Your music, together'),('sound','Playback','Sound & listening'),('settings','Appearance','Theme · fonts · icons'),('nav_library','Library','Downloads & your music')])
 settings=f'''<article class="phone settings"><div class="top">{button('back')}<span>YOUR SPACE</span>{button('settings')}</div><h2>Settings</h2><div class="panel"><div class="row">{g('nav_search')}<span>Search settings</span></div></div><p>Make room for your own rhythm.</p><div class="panel">{rows}</div><div class="panel"><div class="row">{g('animation')}<span>Screen animations<em>Native theme motion</em></span><div class="switch">{g('switch_on')}</div></div>{track(m)}<p class="note">Theme artwork intensity</p></div>{nav}</article>'''
 strip=''.join(g(k) for k in ['nav_home','nav_search','nav_explore','nav_library','play','pause','previous','next','shuffle','repeat','queue','lyrics','settings','account','download','seek_thumb'])
 cover=''.join(f'<div>{k.replace("_"," ")}</div>' for k in a)
 screen=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{c['name']} · complete theme study</title><style>{fonts}{vars}{CSS}</style><main><header><div><small>VEYRA / ADVANCED WORLDS / {c['medium'].upper()}</small><h1>{c['name']}</h1><p>{c['description']}</p></div>{g('brandIcon',100)}</header><div class="palette">{''.join(f'<i style="background:{v}"></i>' for v in p.values())}</div><section class="phones">{home}{player}{settings}</section><p class="note">Actual pack artwork, glyphs, fonts and palette in browser design studies. These are not Android screenshots. Native geometry and motion are implemented in beta build 31; content here is illustrative.</p><div class="strip">{strip}</div><h2>119 asset roles · one coherent world</h2><p>113 functional glyphs + in-app brand + two fonts + three artwork roles sharing one original illustration. All assets are shown on the <a href="assets.html">full asset sheet</a>.</p><div class="coverage">{cover}</div><p class="note">Original Home, player, Settings and deep screens share the active pack. Optional custom Home styles keep their own identity. Service logos, real album artwork, launcher aliases and accessibility remain native. Motion respects app/system preferences; device FPS has not been measured.</p></main></html>'''
 cards=[]
 for k,v in a.items():
  if k.endswith('Font'):sample=f'<div class="{"heading" if k=="headingFont" else "body"}">Your kind of music.<br>Aa Bb 012345</div>'
  else:sample=f'<img class="{"art" if k in ["header","player","preview"] else "brand" if k=="brandIcon" else "glyph"}" src="{prefix}{v}" alt="{k}">'
  cards.append(f'<article class="asset {"wide" if k.endswith("Font") or k in ["header","player","preview"] else ""}"><div class="sample">{sample}</div><h3>{k.replace("_"," ").title()}</h3><code>{v}</code></article>')
 assets=f'<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{c["name"]} · every asset</title><style>{fonts}{vars}{ASSET_CSS}.grid{{grid-template-columns:repeat(6,minmax(0,1fr));gap:12px}}.sample{{height:70px}}.asset{{padding:10px}}.asset h3{{font-size:16px}}.wide .sample{{height:160px}}.glyph{{width:46px;height:46px}}.heading,.body{{font-size:27px}}h1{{font-size:54px}}</style><main><span class="eyebrow">VEYRA · BUILD 31 · COMPLETE ASSET INVENTORY</span><h1>{c["name"]}</h1><p>All {len(a)} asset roles. Transparent PNG glyphs, original SVG masters and font licenses included. Native progress decoration is drawn from the bounded {c["seek"]} preset. Header, Player and Studio deliberately share the same artwork file.</p><div class="grid">{"".join(cards)}</div></main></html>'
 return screen,assets

def render(out):
 out=Path(out);out.mkdir(parents=True,exist_ok=True)
 for c in COLLECTION:
  folder=out/c['id'];shutil.copytree(ROOT/c['id'],folder/'assets',dirs_exist_ok=True);shutil.copytree(ROOT/'source-icons'/c['id'],folder/'vectors',dirs_exist_ok=True)
  for suffix in ['.zip','.zip.sha256']:shutil.copyfile(ROOT/'packs'/f'{c["id"]}-v1{suffix}',folder/f'{c["id"]}-v1{suffix}')
  for prefix,where in [('assets/',folder),('../../'+c['id']+'/',ROOT/'previews'/c['id'])]:
   where.mkdir(parents=True,exist_ok=True);screens,assets=make(c,prefix);(where/'index.html').write_text(screens);(where/'assets.html').write_text(assets)
 # Reuse an overview layout with this collection's actual assets/fonts.
 import render_illustrated_gallery as gallery
 gallery.COLLECTION=[dict(c,scene=c['material']) for c in COLLECTION]
 for prefix,where in [(lambda key,path:key+'/assets/'+path,out),(lambda key,path:'../../'+key+'/'+path,ROOT/'previews/advanced-worlds')]:
  where.mkdir(parents=True,exist_ok=True)
  page=gallery.overview(prefix).replace('lantern-letters','switchback-radio').replace('fonts/PatrickHand.ttf','fonts/Rajdhani.ttf')
  page=page.replace('Illustrated Worlds','Advanced Worlds').replace('ILLUSTRATED WORLDS','ADVANCED WORLDS').replace('Five little universes. Yours to play.','Five worlds. Every control belongs.').replace('Ink & watercolor / retro risograph / botanical engraving / hand-painted gouache / layered cut paper','Pixel nocturne / botanical cinema / architectural dusk / motorsport / anime flame').replace('65 functional glyphs','565 functional glyphs').replace('supported build-30 presets','five new native control & progress presets').replace('Playful spring press','Custom geometry · seek · native motion').replace('complete 19-role','complete 119-role').replace('build 30','build 31').replace('COLLECTION 01','COLLECTION 02')
  for c in COLLECTION:
   link=c['id']+'/index.html' if where==out else '../'+c['id']+'/index.html'
   title=html.escape(c['name'])
   page=page.replace('>'+title+'</h2>','><a style="color:inherit;text-decoration:none" href="'+link+'">'+title+'</a></h2>')
  (where/'index.html').write_text(page)
 if out.name=='Advanced-Worlds':
  (out/'README.md').write_text('Open index.html to compare themes, then each theme/index.html for screen studies and assets.html for every asset. These are browser design studies, not Android screenshots. Installable .zip packs require Veyra 0.1.9-beta1 build 31. Artwork/brand/fonts/glyphs, original SVG masters and licenses are included.\n')
if __name__=='__main__':
 import sys;render(sys.argv[1])
